gen('she × see','/ʃ/ × /s/','/ʃ/ = “ch” suave; /s/ = “ss”.',[('she','see'),('ship','sip')])
gen('they × day','/ð/ × /d/','/ð/ língua entre os dentes.',[('they','day'),('then','den')])
gen('Subida no final','↗','A voz sobe no fim de perguntas de sim/não.',[('Ready? ↗','Ready. ↘')])
gen('Pergunta com palavra','↘','Perguntas com wh- descem no fim.',[('Where? ↘','Here? ↗')])
gen('E × I','/i/ × /aɪ/','E = /i/, I = /aɪ/ no alfabeto.',[('E','I')])
